DROP TABLE IF EXISTS `farmer_crops`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `farmer_crops` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `farmer_id` bigint NOT NULL,
  `land_id` bigint DEFAULT NULL,
  `crop_id` bigint NOT NULL,
  `variety_id` bigint DEFAULT NULL,
  `season` enum('KHARIF','RABI','ZAID') COLLATE utf8mb4_unicode_ci NOT NULL,
  `season_year` int NOT NULL,
  `sowing_date` date DEFAULT NULL,
  `expected_harvest_date` date DEFAULT NULL,
  `actual_harvest_date` date DEFAULT NULL,
  `area_sown` decimal(38,2) DEFAULT NULL,
  `area_unit` enum('HECTARE','ACRE','BIGHA','GUNTA') COLLATE utf8mb4_unicode_ci DEFAULT 'ACRE',
  `expected_yield` decimal(38,2) DEFAULT NULL,
  `actual_yield` decimal(38,2) DEFAULT NULL,
  `yield_unit` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_input_cost` decimal(38,2) DEFAULT NULL,
  `total_revenue` decimal(38,2) DEFAULT NULL,
  `status` enum('PLANNED','SOWN','GROWING','HARVESTED','FAILED') COLLATE utf8mb4_unicode_ci DEFAULT 'PLANNED',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `land_id` (`land_id`),
  KEY `crop_id` (`crop_id`),
  KEY `variety_id` (`variety_id`),
  KEY `idx_farmer_crops_farmer` (`farmer_id`),
  KEY `idx_farmer_crops_season` (`season`,`season_year`),
  KEY `idx_farmer_crops_status` (`status`),
  CONSTRAINT `farmer_crops_ibfk_1` FOREIGN KEY (`farmer_id`) REFERENCES `farmer_profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `farmer_crops_ibfk_2` FOREIGN KEY (`land_id`) REFERENCES `farmer_lands` (`id`) ON DELETE SET NULL,
  CONSTRAINT `farmer_crops_ibfk_3` FOREIGN KEY (`crop_id`) REFERENCES `crops` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `farmer_crops_ibfk_4` FOREIGN KEY (`variety_id`) REFERENCES `crop_varieties` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

